function probeDepth() {
  let depth = 0;
  function recurse() { depth++; recurse(); }
  try { recurse(); } catch (e) { return depth; }
}
const limit = probeDepth();
console.log('Max recursion depth before overflow:', limit);
console.log('This is the few-thousand-to-tens-of-thousands hard cap (~10^4-10^5 frames).');
let acc = 0;
for (let i = 0; i < limit * 100; i++) acc += 1;
console.log('Iterative loop ran', limit * 100, 'steps with O(1) stack — no overflow.');
